      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine extraordinary precision with a major advance in controlling and measuring atomic systems. They have opened new tests of fundamental physics as well as practical applications.",
        "attribution": "Katori and Ye made complementary, independent contributions to the optical lattice clock concept and its realization.",
        "maturity": "The method is well established, independently developed, and repeatedly demonstrated at ever higher precision.",
        "uncertainties": [
          "The balance between the fundamental measurement advance and its later applications would need careful framing."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Christophe Salomon",
        "Rudolf Grimm",
        "Wolfgang Ketterle"
      ],
      "assessment": {
        "nobel_worthiness": "Strongly interacting Fermi gases provide a clean and tunable setting for exploring universal quantum matter and many-body behavior that is difficult to access in ordinary materials.",
        "attribution": "These researchers led major experimental advances across complementary regimes and laboratories; credit should reflect the field's broader experimental and theoretical foundations.",
        "maturity": "The systems have been studied for decades, with extensive confirmation and continuing use as benchmarks for many-body theory.",
        "uncertainties": [
          "The specific discovery to be recognized needs delimiting within a broad experimental program."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices turned ultracold atoms into controllable quantum simulators, allowing direct study of important many-body models and phases.",
        "attribution": "Bloch and Greiner established landmark experiments, while Zoller supplied central theoretical proposals. Cirac also contributed substantially, so a three-person limit makes attribution difficult.",
        "maturity": "The platform is mature and has supported reproducible experiments across many laboratories.",
        "uncertainties": [
          "The boundary between this achievement and related quantum simulation and atomic information work is not sharp."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics established a powerful way to couple and control individual quantum systems using superconducting circuits, with major consequences for quantum optics and information.",
        "attribution": "Blais developed key theory; Wallraff and Schoelkopf led seminal experimental demonstrations and development.",
        "maturity": "The basic effects have been reproduced widely and the platform now supports increasingly sophisticated control.",
        "uncertainties": [
          "Its broad scope could make it difficult to identify a single prize-sized contribution."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Theoretical schemes and experimental control of atomic quantum systems laid important foundations for quantum information processing and simulation.",
        "attribution": "Cirac and Zoller made influential theoretical contributions, and Blatt's group demonstrated trapped-ion control central to the experimental realization.",
        "maturity": "The core methods have been demonstrated and developed across many laboratories, though scalable, fault-tolerant machines remain an ongoing goal.",
        "uncertainties": [
          "This overlaps substantially with the separately listed trapped-ion computation achievement."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can, in principle, be protected from noise, changing the foundations and prospects of quantum computation.",
        "attribution": "Kitaev, Steane, and Shor made distinct foundational contributions, alongside substantial work by many others.",
        "maturity": "The theory is robust and experimental implementations have advanced considerably, although large-scale fault tolerance is not yet routine.",
        "uncertainties": [
          "The field's theoretical and experimental milestones span many contributors and may not map cleanly to a small laureate group."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "John D. Teufel",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of mechanical motion has pushed mesoscopic objects toward the quantum regime and tested the boundary between quantum behavior and ordinary classical motion.",
        "attribution": "The listed researchers represent important experimental advances, but the field spans distinct devices and several additional major contributors.",
        "maturity": "Ground-state cooling and related control techniques are well demonstrated, while preparation and observation of ever larger nonclassical states remain active work.",
        "uncertainties": [
          "The qualifying discovery and the appropriate division of credit across platforms are not settled."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable Rydberg arrays offer an unusually direct route to studying interacting quantum systems and constructing quantum simulators.",
        "attribution": "Browaeys, Saffman, and Lukin represent major experimental and conceptual advances in the platform; Zoller also has an important theoretical role.",
        "maturity": "The platform has rapidly advanced and is reproducible, but its longer-term scientific reach is still emerging.",
        "uncertainties": [
          "It may be too early to distinguish lasting fundamental impact from the promise of the current technology."
        ]
      }
    }
  ]
